import type { CredentialsModel } from "./engine.ts";
import { BUNDLED_CREDENTIAL_MODEL } from "./model-weights.ts";

/**
 * The tiny local credential model.
 *
 * A hashed character n-gram logistic regression with a few thousand int8
 * weights (about 40 KB of source, no runtime dependency, no network). It runs
 * on suspicious tokens the patterns did not already catch — an unlabelled
 * base64 blob, a random-looking password, a key in a shape nobody listed — and
 * answers one question: does this look like a credential?
 *
 * The weights are generated by `scripts/credentials-model/train.py`; the same
 * feature extraction lives there, and the tests pin examples both sides agree
 * on. A newer `model.json` can be downloaded into the CodeitLab home and
 * loaded with `parseCredentialModel`, so the detector can improve without a
 * release while the bundled copy keeps working offline.
 */

export interface CredentialModelWeights {
  id: string;
  version: string;
  algorithm: string;
  buckets: number;
  ngrams: ReadonlyArray<number>;
  denseFeatures: ReadonlyArray<string>;
  scale: number;
  bias: number;
  threshold: number;
  weights: ReadonlyArray<number>;
}

const SECRET_CONTEXT_WORDS = [
  "password",
  "passwd",
  "pwd",
  "secret",
  "token",
  "apikey",
  "api_key",
  "api-key",
  "key",
  "credential",
  "auth",
  "bearer",
  "private",
] as const;

const KNOWN_PREFIXES = [
  "sk-ant-api03-",
  "sk-ant-",
  "sk-proj-",
  "sk-",
  "ghp_",
  "gho_",
  "ghu_",
  "ghs_",
  "ghr_",
  "github_pat_",
  "glpat-",
  "AKIA",
  "ASIA",
  "AIza",
  "xoxb-",
  "xoxp-",
  "xoxa-",
  "xoxr-",
  "npm_",
  "sk_live_",
  "rk_live_",
  "whsec_",
] as const;

/** FNV-1a over the UTF-8 bytes of the feature string, exactly like the trainer. */
export function fnv1a32(text: string): number {
  let hash = 0x811c9dc5;
  const bytes = new TextEncoder().encode(text);
  for (const byte of bytes) {
    hash ^= byte;
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash >>> 0;
}

function shannonEntropy(value: string): number {
  if (value.length === 0) return 0;
  const counts = new Map<string, number>();
  for (const char of value) counts.set(char, (counts.get(char) ?? 0) + 1);
  let entropy = 0;
  for (const count of counts.values()) {
    const p = count / value.length;
    entropy -= p * Math.log2(p);
  }
  return entropy;
}

function ratioOf(chars: string, value: string): number {
  if (value.length === 0) return 0;
  let count = 0;
  for (const char of value) if (chars.includes(char)) count += 1;
  return count / value.length;
}

const HEX_RE = /^[0-9a-fA-F]+$/;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

function denseFeatures(token: string, context: string): number[] {
  const lower = token.toLowerCase();
  const ctx = context.toLowerCase();
  const length = token.length;
  const digits = ratioOf("0123456789", token);
  const entropy = shannonEntropy(token);
  const hasSecretContext = SECRET_CONTEXT_WORDS.some((word) => ctx.includes(word));
  const upper = ratioOf("ABCDEFGHIJKLMNOPQRSTUVWXYZ", token);
  const base64ish = /^[A-Za-z0-9+/_-]+={0,2}$/.test(token);
  const codeish =
    /^[a-z]+[A-Z][A-Za-z0-9]*$/.test(token) ||
    /^[a-z0-9]+_[a-z0-9_]+$/.test(token) ||
    token.includes("/") ||
    token.includes(".");
  return [
    1,
    length < 12 ? 1 : 0,
    length >= 12 && length < 20 ? 1 : 0,
    length >= 20 && length < 32 ? 1 : 0,
    length >= 32 && length < 48 ? 1 : 0,
    length >= 48 ? 1 : 0,
    digits < 0.15 ? 1 : 0,
    digits >= 0.15 && digits < 0.4 ? 1 : 0,
    digits >= 0.4 && digits < 0.7 ? 1 : 0,
    digits >= 0.7 ? 1 : 0,
    /[A-Z]/.test(token) && /[a-z]/.test(token) ? 1 : 0,
    token === token.toUpperCase() && token !== token.toLowerCase() ? 1 : 0,
    token === token.toLowerCase() ? 1 : 0,
    /[^A-Za-z0-9]/.test(token) ? 1 : 0,
    HEX_RE.test(token) ? 1 : 0,
    UUID_RE.test(lower) ? 1 : 0,
    token.includes("/") ? 1 : 0,
    KNOWN_PREFIXES.some((prefix) => token.startsWith(prefix)) ? 1 : 0,
    ctx.includes("password") || ctx.includes("passwd") || ctx.includes("pwd") ? 1 : 0,
    ctx.includes("secret") ? 1 : 0,
    ctx.includes("token") ? 1 : 0,
    ctx.includes("auth") ? 1 : 0,
    ctx.includes("key") ? 1 : 0,
    ctx.includes("credential") ? 1 : 0,
    ctx.includes("bearer") ? 1 : 0,
    hasSecretContext ? 0 : 1,
    entropy < 2.5 ? 1 : 0,
    entropy >= 2.5 && entropy < 3.5 ? 1 : 0,
    entropy >= 3.5 && entropy < 4.5 ? 1 : 0,
    entropy >= 4.5 ? 1 : 0,
    token.includes("-") ? 1 : 0,
    token.includes("_") ? 1 : 0,
    token.includes(".") ? 1 : 0,
    /[0-9]/.test(token) && /[A-Za-z]/.test(token) ? 1 : 0,
    base64ish ? 1 : 0,
    upper < 0.3 ? 1 : 0,
    upper >= 0.3 && upper < 0.7 ? 1 : 0,
    upper >= 0.7 ? 1 : 0,
    length >= 16 && length < 24 ? 1 : 0,
    length >= 24 && length < 40 ? 1 : 0,
    codeish ? 1 : 0,
  ];
}

/** Sparse feature indices, in the trainer's order. */
export function credentialFeatureIndices(
  token: string,
  context: string,
  weights: Pick<CredentialModelWeights, "buckets" | "ngrams">,
): number[] {
  const lower = token.toLowerCase();
  const indices: number[] = [];
  for (const n of weights.ngrams) {
    for (let i = 0; i <= lower.length - n; i += 1) {
      indices.push(fnv1a32(`g${n}:${lower.slice(i, i + n)}`) % weights.buckets);
    }
  }
  const dense = denseFeatures(token, context);
  for (let i = 0; i < dense.length; i += 1) {
    if (dense[i] === 1) indices.push(weights.buckets + i);
  }
  return indices;
}

export function scoreWithCredentialModel(
  token: string,
  context: string,
  weights: CredentialModelWeights,
): number {
  let sum = weights.bias;
  for (const index of credentialFeatureIndices(token, context, weights)) {
    sum += weights.scale * (weights.weights[index] ?? 0);
  }
  return 1 / (1 + Math.exp(-sum));
}

export interface TinyCredentialModel extends CredentialsModel {
  readonly threshold: number;
  readonly sizeBytes: number;
}

/** The bundled model; always available, no download, no network. */
export function bundledCredentialModel(): TinyCredentialModel {
  return modelFromWeights(BUNDLED_CREDENTIAL_MODEL as unknown as CredentialModelWeights);
}

function modelFromWeights(weights: CredentialModelWeights): TinyCredentialModel {
  const threshold = weights.threshold;
  return {
    id: weights.id,
    version: weights.version,
    threshold,
    sizeBytes: weights.weights.length,
    score(token: string, context = ""): number {
      return scoreWithCredentialModel(token, context, weights);
    },
  };
}

/** Parse a downloaded `model.json`, rejecting anything that is not the expected shape. */
export function parseCredentialModel(json: string): TinyCredentialModel {
  const parsed: unknown = JSON.parse(json);
  if (parsed === null || typeof parsed !== "object") {
    throw new Error("Credential model file is not an object.");
  }
  const record = parsed as Record<string, unknown>;
  const weights = record.weights;
  const buckets = record.buckets;
  const ngrams = record.ngrams;
  const dense = record.denseFeatures;
  const scale = record.scale;
  const bias = record.bias;
  const threshold = record.threshold;
  if (
    typeof record.id !== "string" ||
    typeof record.version !== "string" ||
    typeof buckets !== "number" ||
    !Array.isArray(ngrams) ||
    !Array.isArray(dense) ||
    !Array.isArray(weights) ||
    typeof scale !== "number" ||
    typeof bias !== "number" ||
    typeof threshold !== "number" ||
    weights.length !== buckets + dense.length ||
    !Number.isFinite(scale) ||
    !Number.isFinite(bias) ||
    !Number.isFinite(threshold)
  ) {
    throw new Error("Credential model file has an unexpected shape.");
  }
  return modelFromWeights({
    id: record.id,
    version: record.version,
    algorithm:
      typeof record.algorithm === "string" ? record.algorithm : "hashed-char-ngram-logreg-int8",
    buckets,
    ngrams: ngrams as number[],
    denseFeatures: dense as string[],
    scale,
    bias,
    threshold,
    weights: weights as number[],
  });
}

export const CREDENTIAL_MODEL_CONTEXT_WORDS = SECRET_CONTEXT_WORDS;
